import{_ as o,o as u,c as q,ag as l}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"11 玄学商战与考据知识","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/11_玄学商战与考据知识.md","filePath":"topics/tianya/handbook/11_玄学商战与考据知识.md"}'),i={name:"topics/tianya/handbook/11_玄学商战与考据知识.md"};function r(n,t,s,a,g,e){return u(),q("div",null,[...t[0]||(t[0]=[l('<h1 id="_11-玄学商战与考据知识" tabindex="-1">11 玄学商战与考据知识 <a class="header-anchor" href="#_11-玄学商战与考据知识" aria-label="Permalink to &quot;11 玄学商战与考据知识&quot;">​</a></h1><p>来源：天涯神贴 97、28、33、30、31、162、187、71、96、186、190、154、111。本手册只整理帖内知识并标注帖号；编者补注一律标&quot;编者注&quot;，与帖子内容区分。</p><hr><h2 id="a-玄学预测术知识框架" tabindex="-1">A 玄学预测术知识框架 <a class="header-anchor" href="#a-玄学预测术知识框架" aria-label="Permalink to &quot;A 玄学预测术知识框架&quot;">​</a></h2><p><strong>成色声明</strong>：本部分分三档。①文化知识档：四门术数的分工体系、术语表、起卦流程、面相术语——可作民俗文化知识学习，历代文献有据。②可操作方法档：六爻起卦步骤、三停六府观察顺序——流程明确，但其有效性没有任何受控证据。③作者个人断言档：一切&quot;百分之百灵验&quot;&quot;木星到某宫必然倒霉&quot;类断言均系个人宣称，不可证伪，当信念产品看待。</p><h3 id="a1-四门总纲-术数的分工体系-97" tabindex="-1">A1 四门总纲：术数的分工体系（97） <a class="header-anchor" href="#a1-四门总纲-术数的分工体系-97" aria-label="Permalink to &quot;A1 四门总纲：术数的分工体系（97）&quot;">​</a></h3><ul><li><strong>分工表</strong>：易经为群经之首；奇门遁甲讲时空变化，&quot;运用时空变化百战百胜，主要是打仗&quot;；太乙神数讲天运变化，&quot;测国家某地哪年会出现地震、天灾以及国运变化&quot;；大六壬是人事变化，&quot;主测人事，吉凶祸福&quot;。四门之外有七政四余（&quot;择日至高法门&quot;），再下是紫微斗数、铁板神数、梅花易数、六爻、八字、风水、符咒、民间法术，合称&quot;玄学&quot;。（97）</li><li><strong>总根子</strong>：一切预测术的根子是日月五星运行。&quot;讲阴阳、五行、天干、地支、六十甲子，说白了讲的是日月五星运行，直接刨到祖坟上了。&quot;（97）</li><li><strong>运算思路示例</strong>： <ul><li>岁差改卦：春分点每年西移 50.26 角秒，伏羲时代春分点在亥宫零度，文王时代已移到戌宫零度，&quot;整整差了一个宫位三十度&quot;，所以先天八卦&quot;算不准了&quot;，文王重排为后天八卦；&quot;过上千年太阳到酉宫零度，现在的后天八卦也不合以后的自然规律&quot;。（97）编者注：50.26 角秒/年约合 71.6 年差一度、2148 年差一宫，作者的时间账算得粗糙，但岁差本身是真实天文现象，用&quot;岁差导致天文基准漂移、需要换坐标系&quot;来解释先后天八卦，是全帖最像知识的一段。</li><li>十二生肖：木星公转 11.86 年，取整十二年配地支；&quot;子年木星对地球的影响，气场和老鼠的习性比较像&quot;，故子为鼠、寅为虎；属龙者是&quot;古人凭空想的一种生物&quot;以补气场无对应动物之缺。（97）</li><li>天道＝黄经道：&quot;太阳运行一周天对地球造成的生长生发收敛收藏的过程就叫做道&quot;；月亮行至毕宿、箕宿对应地球某经纬度降雨刮风，&quot;月之从星，有降雨之处便有刮风之处&quot;。（97）</li></ul></li><li><strong>命与改运</strong>：运气由日月五星运行度数决定；改运原理是&quot;在天成象，在地成形&quot;——天上的&quot;象&quot;克你，天改不了，就用地上对应的&quot;形&quot;间接化解。操作三件套：择日（应天时）＋特殊材质（符纸、金银玉，用地力）＋念咒（启动）。限制条件说得直白：&quot;好像开空调，家里不热了，但你没法让整个城市不热；戴上有效，摘了就没&quot;——改运只能免灾，不能让人&quot;戴个东西赚几千万&quot;；且必须&quot;顺天&quot;不能&quot;逆天&quot;。（97）</li><li><strong>中医＝易经分支论</strong>：&quot;地球上的万物全是中药&quot;，草根树皮能治病与风水摆物同理；&quot;把治病看成改运&quot;——知道熬夜伤肾就不熬夜、知道某地方克你就不去那里上班，都是改运。这是全帖最可自查、最少玄味的一段。（97）</li><li><strong>成色评价</strong>：天文历法部分（岁差、行星周期、黄经）教科书级正确；从&quot;木星气场决定性格&quot;起进入断言区（含 1986 年木星到亥宫的换算、&quot;免费算卦损运气&quot;）；作者自认&quot;主业是中医，玄学是爱好&quot;。当&quot;术数世界观导览&quot;是上品，当操作手册不可信。</li></ul><h3 id="a2-六爻纳甲-起卦的实操入门-33-兼及-28" tabindex="-1">A2 六爻纳甲：起卦的实操入门（33，兼及 28） <a class="header-anchor" href="#a2-六爻纳甲-起卦的实操入门-33-兼及-28" aria-label="Permalink to &quot;A2 六爻纳甲：起卦的实操入门（33，兼及 28）&quot;">​</a></h3><ul><li><strong>体系区分</strong>（33）：&quot;摇三枚铜钱那个叫六爻，也叫纳甲，是占卜的大宗之法；用出生的年月日时来推命叫四柱或子平八字。一个是占卜、一个是星宗，虽然基础理论都是阴阳五行，但区别很大。&quot;——一个叫算卦，一个叫算命。</li><li><strong>起卦流程</strong>（33 全程示范）： <ol><li>前提条件：对&quot;心诚则灵&quot;给出机制解释——信者心无旁念、信息聚焦，不信者杂讯一并传到卦上，&quot;问此而映它&quot;。楼主据此立<strong>八不测</strong>，如&quot;嬉戏嘈杂不测&quot;（问卦态度不正或环境不好不测）、&quot;酒后迷时不测&quot;（喝酒后心意迷乱不能摇卦）。（33）</li><li>起卦：三枚铜钱合手摇六次，脑中默想所问之事，掷于桌面，自下而上记录每爻。</li><li>成卦装卦：得本卦与变卦（如水山蹇变水地比）；按《浑天纳甲歌》配地支（&quot;乾金甲子外壬午，坎水戊寅外戊申……&quot;），标<strong>六亲</strong>（父母、兄弟、子孙、妻财、官鬼）、<strong>六神</strong>（青龙、玄武、白虎、螣蛇、勾陈、朱雀，按起卦日的天干排）、<strong>世应</strong>。楼主承认：没有老师教，&quot;把纳甲规则的歌诀给你也看不懂&quot;。</li><li>定用神：测什么取什么六亲。父亲测女儿取<strong>子孙爻</strong>；测考试&quot;以父母爻为第一用神（一切庇护我者皆为父母），官鬼爻为第二用神（求官求名求工作事业）&quot;，文契、文书、股票皆以父母爻为用神；求财用妻财；男测感情看财、女看官杀。</li><li>断旺衰生克：用神得月令日辰生扶为旺；动爻生用神为助、冲克用神为凶（如&quot;官鬼午火冲用神子水=进了坏人圈&quot;，但午火受亥月亥日之克=&quot;坏人必被拿获&quot;）。</li><li>断应期：按地支轮值定应验日期（&quot;最早丑日、最迟卯日&quot;）；楼主自认应期&quot;太复杂，一句两句说不清&quot;。</li></ol></li><li><strong>案例逻辑</strong>（33 老陈寻女卦）：子孙爻上六子水为用神→三爻申金发动生之=&quot;不死之象&quot;；子水居北方＋变卦为归魂、&quot;归魂不出疆&quot;=&quot;人在长沙北郊&quot;；三爻申金化卯木生扶用神=&quot;过几天她会回来&quot;。事后按楼主叙述全部应验。</li><li><strong>八字速览</strong>（33 周胖子媳妇）：坤造戊午年戊午月壬戌日戊申时——&quot;官杀太重，官弱杀强&quot;，女命看官杀故感情对象多；乙卯大运辛卯流年，&quot;卯是她的正桃花&quot;，应期在流年。</li><li><strong>风水一例</strong>（33）：小赵家房子缺东北角，艮为少男，应在小儿身上。</li><li><strong>成色评价</strong>：流程是真实传承的占卜技术，步骤完整可操作；《卜筮正宗》《增删卜易》确为业内公认教材。但卦例应验全为楼主自述、无对照验证；其逻辑实为&quot;先给结论再找卦中理由&quot;的叙事闭环。当作文化遗产与决策辅助仪式来学，不要当预测工具用。</li></ul><h3 id="a3-面相学-改行为改命-的逻辑-30-31" tabindex="-1">A3 面相学：&quot;改行为改命&quot;的逻辑（30/31） <a class="header-anchor" href="#a3-面相学-改行为改命-的逻辑-30-31" aria-label="Permalink to &quot;A3 面相学：&quot;改行为改命&quot;的逻辑（30/31）&quot;">​</a></h3><ul><li><strong>核心论法</strong>：面相是心性与行为的长期外化，所以&quot;相随心转&quot;；反过来观相可知一个人的行为惯性，修行为即可改相改命。定调：&quot;名为教人看相，实为授人心法。&quot;&quot;改变自己命运的唯一办法就是帮助别人。&quot;（30）</li><li><strong>小学课程（三停六府）——五官对应行为模式的读法</strong>： <ul><li>上停（发际线至眉上沿）：主聪明、祖荫、早年运，必须与耳朵互证——耳朵主童年 1—14 岁，与大脑同步发育。上停高而耳差＝只是得长辈疼爱而非聪明（30 虹雨案例：高额头被误判聪明安排做统计，小薄耳暴露了学习能力）。</li><li>中停：鼻梁＝事业宫（女命兼主夫运，楼主称&quot;准确度 90%&quot;）；颧骨与中二府主交际；鼻头＝财富宫，鼻翼＝财库（&quot;没有财库就是存不到钱&quot;）。</li><li>下停：主稳重、晚年运、子女运；嘴主度量，&quot;嘴大吃四方&quot;。</li><li>六府（上中下三对二府）辅助判断三停的&quot;发力点&quot;；楼主宣称三停六府自测可达&quot;80%的准确度&quot;。</li></ul></li><li><strong>中学课程（十二宫、四渎五岳）</strong>：田宅宫（上眼睑）被楼主改注为&quot;好田宅&quot;——主对家庭父母的依恋（孝），论据是&quot;欧美白人眉压眼几乎没有上眼睑，难道欧美人都没有房子？但家庭观念淡薄有目共睹&quot;——这是全帖少见的&quot;跨文明反证&quot;思路。官禄宫＝天庭饱满但须配神态；四渎＝耳、眼、鼻、口（&quot;能存水&quot;的孔窍），五岳以鼻为首。</li><li><strong>大学课程（流年为风、定位为水）</strong>： <ul><li>牌局论：&quot;高手首先要摸清楚牌局的规律，然后给自己手里的牌做个定位，规划好后面怎么出牌。&quot;本帖教你看牌（面相＝人生规律＋手中牌），《定位》教规划，《商道风水》讲赢钱。</li><li>财富流动性史：90 年代前社会流动性小→房改、按揭（&quot;银行把未来二十年的工作能力折现给开发商&quot;）→08 年流动性登峰→15 年房地产绑架经济；个人层面&quot;现金流不容易作假，存款可以&quot;——银行看流水不看余额。</li><li>修相：同一人十年间眉毛由上扬变下弯＝心性由张扬变善良，&quot;相由心生&quot;的直接证据；&quot;恩爱的夫妻越长越像&quot;；整容&quot;有风险，有时效性&quot;，改不了心性；&quot;多笑&quot;是最便宜的改相。</li></ul></li><li><strong>研究生课程（《冰鉴》相神，30/31）</strong>：&quot;下相相形，上相相神，相神的八成功力在眼&quot;——眼神清浊高于五官形状；声音四喻：&quot;喜如折竹，怒如阴雷起地，哀如击薄冰，乐如雪舞风前&quot;。</li><li><strong>约法三章</strong>（30）：不得以此牟利；给求相者希望；未成年人不相。</li><li><strong>成色评价</strong>：三停六府十二宫是相学术语体系的优质通俗化，观察顺序可操作；&quot;行为改变面相&quot;在神态、皱纹层面有生活观察支撑，&quot;五官定富贵&quot;无证据。帖子的真实价值在定位理论与劝善框架，相术是它的教学钩子；赏金六万印书三千册，是天涯少见的知识变现样本。</li></ul><h3 id="a4-灵宠帖的民俗动物观-187" tabindex="-1">A4 灵宠帖的民俗动物观（187） <a class="header-anchor" href="#a4-灵宠帖的民俗动物观-187" aria-label="Permalink to &quot;A4 灵宠帖的民俗动物观（187）&quot;">​</a></h3><ul><li><strong>出发点是拆台</strong>：真开光要求高道行、自损根基，市面开光玉基本是商业骗局；因此提出&quot;请块开光玉，不如养活的灵宠&quot;。</li><li><strong>五种灵宠谱系</strong>： <ul><li>龟＝玄武苗裔：镇宅积福，认主后三五年见效，&quot;在自己一亩三分地上很罩得住&quot;，但不能出门；草龟才灵，巴西龟&quot;留了洋&quot;不算。</li><li>雄鸡＝朱雀：&quot;打生来就是与一切阴邪恶鬼相克&quot;，战宠之首；&quot;土里千年，不敌好鸡一只&quot;。</li><li>猫＝白虎：灵力极强但属阴，难养熟；蛇同理，&quot;阴气太戾，杀心极炽&quot;，极难认主。</li><li>狗：预警＋护主，发起狠来&quot;阴阳通吃&quot;；民俗口诀&quot;白灵，黑凶，满地金&quot;（白狗灵通知人意、黑狗凶悍善斗妖邪、黄狗识势安家旺财）；黑狗血、黑狗牙是旧时法事道具。</li><li>鹅：见鬼、生气足，预警能力比狗强，但战力有限，&quot;报警器加肉盾&quot;。</li><li>鲤鱼＝青龙：四大灵宠中最特殊，本质极阴却珍贵（&quot;补的是魂&quot;）；养足十年、日日亲喂并念全篇《道德经》方能通灵，技能是&quot;替身挡劫&quot;——挡一劫消一劫，主人无恙而鱼身无故添伤（楼主讲香港电影圈&quot;老离&quot;锦鲤带刀痕头洞挡五劫的故事）；鲤鱼脑门年久凸起开裂即&quot;跃龙门&quot;脱壳，附会杭州&quot;巨大鱼皮&quot;旧闻。</li></ul></li><li><strong>规矩</strong>：灵宠只能&quot;养&quot;不能&quot;请&quot;、不能拜，主仆分清；鲤鱼不可混养、一人一次一条；风水&quot;宜静不宜动&quot;。</li><li><strong>成色评价</strong>：作为民俗动物志（镇宅神兽谱系＋开光产业内幕）是上品；作为&quot;养龟旺运&quot;的方法不可证。楼主反复打补丁：&quot;灵宠只是辅助，最主要的还是要靠自己去挣&quot;&quot;邻居投诉、口舌是非，实在比鬼怪难搞得多&quot;——这种自我克制反而增加其人格可信度。</li></ul><h3 id="a5-附-经济-规律派-预测框架-162" tabindex="-1">A5 附：经济&quot;规律派&quot;预测框架（162） <a class="header-anchor" href="#a5-附-经济-规律派-预测框架-162" aria-label="Permalink to &quot;A5 附：经济&quot;规律派&quot;预测框架（162）&quot;">​</a></h3><ul><li><strong>总纲</strong>：&quot;政策决定短期，规律决定长期。&quot;政策只能改变波形，改不了趋势。</li><li><strong>方法</strong>：分析任何经济现象，先分两层——规律层（人口、成本、产业竞争力）与政策层（货币、税制、行政命令），再判断政策是顺应还是对抗规律。帖内应用：拯救制造业是中国经济主线，路径＝降收入（劳动力成本）＋降成本（制度成本）；&quot;反通胀死循环&quot;的拆解；&quot;房地产税一定会推出，但一定不会很快&quot;；LPR 改革与地摊经济的逻辑链推演。</li><li><strong>成色评价</strong>：无数据模型，属观点型时评；但框架自洽、少情绪词，&quot;规律/政策&quot;两层分离是普通人可迁移的分析习惯。放在玄学卷实为归类错误，恰说明预测术的尽头是常识经济学。</li></ul><hr><h2 id="b-商战与商业知识" tabindex="-1">B 商战与商业知识 <a class="header-anchor" href="#b-商战与商业知识" aria-label="Permalink to &quot;B 商战与商业知识&quot;">​</a></h2><p><strong>成色声明</strong>：①商业知识档：71/96 的商战案例基于公开报道复盘，时间与金额基本可查证，可信度较高；186 的营销理论转述自科特勒《营销管理》与《定位》，属教科书知识。②作者个人断言档：对案例动机的&quot;内幕式&quot;解读（如牛根生预知危机）、营销分级制度、官商生态论断，均为作者个人框架。③编者注档：案例结论的适用性以 2013 年前后的商业环境为界，引用时须注意时效。</p><h3 id="b1-商业筹码类型学-71-96-合并" tabindex="-1">B1 商业筹码类型学（71/96 合并） <a class="header-anchor" href="#b1-商业筹码类型学-71-96-合并" aria-label="Permalink to &quot;B1 商业筹码类型学（71/96 合并）&quot;">​</a></h3><ul><li><strong>界定</strong>：企业在与资本方、竞争方、监管方的博弈中可拿出来交换或制衡的资源即&quot;筹码&quot;。全书八章按筹码类型组织案例。两版关系：71 为天涯首发整理版，96 为标注&quot;已出版&quot;并混入楼层互动的版本，正文一致。</li><li><strong>1 股权筹码与对赌协议（蒙牛案）</strong>：2002 年摩根士丹利、鼎晖、英联以 2600 万美元换蒙牛 32%股权；2003 年签对赌协议（楼主点破实为&quot;看涨期权&quot;）：2003—2006 年复合年增长率不低于 50%，达不到则管理层让渡 6000 万—7000 万股，达标则资方奖励股份。拆解：&quot;这相当于给投资加金融杠杆，让自己投资的风险几乎降为零——输了资方拿股份补偿，赢了资方股份照样大幅增值，风险几乎全部转嫁给经营团队。&quot;对照：太子奶签了如出一辙的对赌，又碰上行业危机，输到丧失领导权；蒙牛赢在协议签于危机前、且提前终止。（71/96）<strong>启示：对赌的本质是杠杆，不是激励。</strong></li><li><strong>2 渠道筹码（雷士照明案）</strong>：吴长江 1998 年以 45%股份创业（两位合伙人合计 55%，股权先天失衡）；2005 年被股东以 8000 万元逼退，三天后凭渠道改革后&quot;经销商权力更大利润更厚&quot;的人心基础，经销商群体倒逼两位股东各以 8000 万元退出；2012 年面对赛富、高盛、施耐德的合围，又&quot;以独立销售网络作为筹码，反过来逼迫国际资本就范&quot;，楼主称之为&quot;中国式商业智慧&quot;的创举。（71/96）<strong>启示：创始人失去股权后，可控渠道是最硬的筹码。</strong></li><li><strong>3 品牌筹码（蒙牛品牌运作）</strong>：牛根生的&quot;第二品牌&quot;战略（不与伊利死磕，借巨人肩膀站位，&quot;行业第二品牌就意味着接近于第一品牌&quot;）；渠道走&quot;小区包围超市&quot;迂回；品牌精神四次注入——2003 非典&quot;健康增强免疫力&quot;、神五&quot;航天专用奶&quot;、2004 央视标王、1400 万冠名超级女声换来酸酸乳 25 亿销售额。楼主同时提示标王的负累：&quot;第一年当标王，就意味着以后也要努力做标王。&quot;（71/96）</li><li><strong>4 资本运作筹码（毛区健丽案）</strong>：雷士资金链危机中，亚盛投资以 1000 万美元买下 30%股份（&quot;低于合理估值的一半&quot;）；亚盛实为中间机构，投入资金一半来自投资人，自己却占股三分之二（雷士 20%）；最终&quot;投资不到 500 万美元，获利近 1 亿美元&quot;。（71/96）<strong>启示：危机中的估值折价，是资本最大的利润来源；信息与胆识就是筹码。</strong></li><li><strong>5 政策/牌照筹码（支付宝案）</strong>：马云以央行牌照发放新规为筹码将支付宝收归独立，&quot;牌照如愿拿到的同时掌控权不旁落&quot;；雅虎股价次日大跌一成，CEO 巴茨数月后下台。（71/96）<strong>启示：监管变化既是风险也是筹码，先手者可借规则重组股权。</strong></li><li><strong>6 商标筹码（王老吉案）</strong>：1995 年加多宝租下广药&quot;王老吉&quot;生产销售权，1997 年租期延至 2010 年 5 月；2001—2003 年陈鸿道以 300 万港币行贿广药总经理李益民，以每年 500 万元续租至 2020 年——非法续约成为日后商标被收回的致命隐患。楼主定调：&quot;在如今的世界经济格局中，商标、专利都成了不可忽视的隐性资产……在国内则更多的是商标之争，一个商标不管有没有产品，都是商业价值。&quot;（71/96）</li><li><strong>7 联盟/人脉筹码（蒙牛危机案）</strong>：2008 年三聚氰胺后蒙牛股价暴跌，牛根生质押给摩根的 4.5%股份面临被动出售；柳传志连夜开董事会，48 小时之内 2 亿元到账，马云、田溯宁等跟进，&quot;民营企业联盟&quot;赎回质押股份。楼主称这是民企&quot;抱团取暖&quot;的风险防范机制——此前一个月牛根生已凭商业触觉出售 3.65%股权套现 12.55 亿港元。（71/96）</li><li><strong>8 产业链整合＝制衡&quot;核弹头&quot;</strong>：中粮&quot;大胃王&quot;并购消化不良的根由是&quot;整体的协同运转无法执行，就相当于整合没做好&quot;；&quot;整合得越合理企业运作成本就越低，净利润率也就越高&quot;——产业链健康的企业才是国际资本撼不动的&quot;核弹头&quot;（新希望的稳健路线为对照）。（71/96）</li><li><strong>&quot;官体商用&quot;生态</strong>（71/96 楼中讨论）：&quot;如果说西方社会是商业社会，那么我们就是官体商用的社会，也就是官为体，商为用……想要有钱必须借助权力通行，而想要升官又必须依靠钱来开路。所以很容易卷入官体争斗中成为牺牲品。&quot;以及&quot;不管发展多么大的企业家，都在为自己留后路，他们是没有安全感的&quot;&quot;政府的职能是服务，而非单纯的收税&quot;。这是全书知识中超出案例本身、最被低估的部分。</li><li><strong>成色评价</strong>：案例复盘属&quot;公开信息＋合理解读&quot;，数字时间基本可靠；筹码类型学是楼主自创框架，但组织力强，至今仍是理解中国式商战的实用透镜；读者质疑（如雷士案未写重庆南岸利益输送）楼主公开认账，态度加分。</li></ul><h3 id="b2-营销体系知识-186" tabindex="-1">B2 营销体系知识（186） <a class="header-anchor" href="#b2-营销体系知识-186" aria-label="Permalink to &quot;B2 营销体系知识（186）&quot;">​</a></h3><ul><li><strong>4P 为何统治教科书</strong>：产品、价格、渠道、促销&quot;让营销人很清晰地探索和执行各自的营销活动&quot;，简单好上手；科特勒后来的 4C、4R、4V、10P、6P、新 4P&quot;都没有达到原来 4P 的普及率&quot;。借院长冯涛之口的判断：&quot;理论概括不一定是越全面越好，而应该是越容易实践越好。往哲学里靠，就是知行合一的意思。&quot;（186）</li><li><strong>营销体系的十条内容</strong>（186，对《营销管理》目录的教学化重组）：研究顾客痛点；分析目标市场并明确定位；打造产品和品牌；建立营销渠道；选择媒体推广；与顾客互动；重视价值和满意度；争取供应链优势资源；保持竞争意识；警惕营销环境。&quot;合格的营销体系就是简约的营销管理方法，能帮助企业在营销层面查漏补缺、有的放矢。&quot;</li><li><strong>消费者行为记忆模型</strong>（186，主角编的打油诗）：&quot;动机即痛点，物质和精神；感知在推广，宣传和体验；学习靠驱动，暗示和强化；情感更吸引，故事和人性；记忆分短长，节点和联想。&quot;背后是标准消费者行为学框架：弗洛伊德动机论（阶梯法、投射技术找潜意识动机）、马斯洛需求五层、感知—学习—情感—记忆链；主角的批注体现批判性：&quot;人的需求从来不是单一的，更不可能是逐步渐进的。&quot;</li><li><strong>定位理论要点</strong>（186 转述《定位》）：定位不改变产品本身，只改名字、价格和包装，&quot;在潜在顾客的心智中占领一个有价值的位置&quot;；基本方法是&quot;操控心智中已经存在的认知&quot;；&quot;在传播过度的社会中，获得成功的唯一希望，是要有选择性，集中火力于狭窄的目标，细分市场&quot;；不要试图改变人类心智；简化信息，一词占领心智；成为第一是进入心智的捷径；不能在此领域得第一，就在另一领域成为第一；告诉潜在顾客新产品&quot;不是什么&quot;。</li><li><strong>学习方法论</strong>（186 郑江平）：读书四阶段——把书读厚（理解并延展，举一反三）→读薄（化繁为简，提炼框架）→再读厚（形成个人注解风格）→读没（&quot;想用书中知识时如探囊取物&quot;）；每篇教材除《营销管理》外须自选两三本书，全课至少二十本书十多次作业。</li><li><strong>营销五级&quot;名、术、融、势、道&quot;</strong>（186，作者原创构思）：名＝能系统说出营销内容并自己下定义（&quot;实上立名&quot;，非公孙龙式的重名不重实）；术＝实践中摸索出自己的方法（如找差异化、定渠道战略）；融＝把名与术融会贯通，提炼自己的道术理论；势＝不仅顺势而为，还要预判&quot;势&quot;提前布局；道＝举重若轻、信手拈来抓本质，能造势开创行业变革，并归于&quot;真善美、大爱的价值观和社会责任心&quot;。</li><li><strong>成色评价</strong>：转述部分（4P 沿革、消费者行为学、定位）是可靠的教科书知识；营销分级无实证，是概念设计；课程结构＝《营销管理》目录＋每篇扩展阅读，作为免费公开课的完成度高于绝大多数商业书。</li></ul><hr><h2 id="c-考据方法论" tabindex="-1">C 考据方法论 <a class="header-anchor" href="#c-考据方法论" aria-label="Permalink to &quot;C 考据方法论&quot;">​</a></h2><p><strong>成色声明</strong>：①可操作方法档：190 的时间线推证、154 的群像史整理法、111 的异象还原法，均为可复制的文本工作方法。②作者个人断言档：190 的傅山作者论与明清影射体系、154 的政治盘口论，属作者观点。③编者注档：红学索隐派与考证派两大传统的背景介绍为编者所加。</p><h3 id="c1-时间线考据法-宝钗大八岁的完整推理-190" tabindex="-1">C1 时间线考据法：宝钗大八岁的完整推理（190） <a class="header-anchor" href="#c1-时间线考据法-宝钗大八岁的完整推理-190" aria-label="Permalink to &quot;C1 时间线考据法：宝钗大八岁的完整推理（190）&quot;">​</a></h3><ul><li><strong>第一步：时间轴重排</strong>（原著第二至四回&quot;文字精确呼应&quot;）：十五岁的薛蟠带十三岁的宝钗入京待选，途中遇十三岁的英莲（葫芦案是一年前的旧案）；十个月后黛玉随贾雨村进京，六岁见七岁宝玉；又两个月贾雨村在金陵结案修书京城；收到书信后的一天，十六岁的薛蟠带十四岁的宝钗进荣国府。结论：薛家入府时宝钗 14 岁、黛玉 6 岁——<strong>大八岁</strong>。</li><li><strong>第二步：身份反推年龄</strong>。袭人全书始终是大丫鬟，贾府 14 岁以下为小丫头；黛玉进府时雪雁 10 岁是小丫头，袭人若只比宝玉大两岁（9 岁）就比雪雁还孩子气，&quot;何谈照顾宝玉&quot;——故袭人此时已满 14 岁。</li><li><strong>第三步：同庚互证</strong>。怡红夜宴占花名点出袭人、宝钗、香菱、晴雯四人同寿数；香菱五岁被拐、七八年后被卖，与宝钗进京时间线吻合——四人皆 14 岁。</li><li><strong>第四步：识别&quot;文学遮掩&quot;</strong>。宝钗十五岁生日被故意挪后到很多年后&quot;突兀写出&quot;，因为生日平淡，&quot;插入到任意章节后拼接一下都一样&quot;，其功能只是点出&quot;过府以后第一个生日就已十五岁&quot;。</li><li><strong>第五步：旁证故事对位</strong>。傅秋芳二十三岁未嫁、其兄傅试想攀贾家——黛玉十五岁时宝钗恰二十三岁；&quot;那些豪门贵族又嫌他本是穷酸&quot;正是薛家被嫌弃的实写。</li><li><strong>第六步：识别&quot;故意错误&quot;</strong>。芦雪广联句说众人都是&quot;十五六七岁&quot;，与已知年龄全面矛盾——&quot;作者就是这样恶搞，也就骗骗愚蠢的人罢了&quot;；&quot;袭人比宝玉大两岁&quot;是&quot;横断的一句，明显错误&quot;。结论：这些错误是风月宝鉴式的筛选器，&quot;上当不上当，其实是文学欣赏水平和智力水平的一次检验&quot;。</li><li><strong>方法论提炼</strong>：①一切以文本内部时间戳互证，不依赖外部权威；②用人物身份与制度门槛（大丫鬟须满 14 岁）反推数值；③把&quot;明显的错误&quot;当作者标记而非抄手讹误；④逐词一致原则——&quot;你每看到的任意一段解释，都是放在后文里也完美匹配的。一个词解释一次，全书以后这个词都是这个意思&quot;。这套流程可迁移到任何有时间线矛盾的经典文本。</li></ul><h3 id="c2-傅山作者论-论证结构与学界对照-190" tabindex="-1">C2 傅山作者论：论证结构与学界对照（190） <a class="header-anchor" href="#c2-傅山作者论-论证结构与学界对照-190" aria-label="Permalink to &quot;C2 傅山作者论：论证结构与学界对照（190）&quot;">​</a></h3><ul><li><strong>帖内论证结构</strong>（七层）： <ol><li>名号互证：石头＝傅山（自号石道人，&quot;取石坚贞之意&quot;），《石头记》即&quot;傅山记&quot;；情僧录之&quot;蘖禅&quot;是傅山法号——&quot;石头记，即傅山记。情僧录，即蘖禅录。&quot;</li><li>履历对位：1644 年大学士李建泰代崇祯出征，聘傅山为军前赞画；傅山投军路上&quot;其军已溃，崇祯也死了，天塌了，但傅山没能起到作用&quot;，日夜痛哭——与女娲炼石&quot;无材可去补苍天&quot;的自况对位。</li><li>学识画像匹配：傅山通庄子、精离骚、是医学大家（山西称&quot;学海&quot;&quot;医圣&quot;）——书中恰有庄子气味、楚辞笔法，且&quot;书中各人所吃食物都暗合各人身份&quot;（宝玉吃榧子&quot;杀治白虫&quot;，白＝雪、虫＝蟠）。</li><li>国权密码：&quot;至贵者为宝，至坚者为玉&quot;——通灵宝玉＝皇权＋国权，如传国玉玺；刻文&quot;莫失莫忘，仙寿恒昌&quot;与玉玺篆文&quot;受命于天，既寿永昌&quot;八字同为篆书、意境相仿。</li><li>断代法：全书提及的历史人物止于元明（倪云林、唐伯虎、祝枝山），&quot;一个清朝的也没有&quot;；&quot;末世&quot;在胡州、金陵、长安各处出现→&quot;国家的末世，朝代的末世&quot;＝明末；&quot;当日地陷东南&quot;呼应天塌地陷的甲申之变。</li><li>避讳式写作：不让用&quot;胡虏&quot;，于是写&quot;葫芦庙&quot;——庙中僧人无发，喻剃发之族。</li><li>人物影射网：甄士隐与通灵宝玉&quot;一面之缘&quot;＝朱由崧弘光政权一年而亡；那僧劝谏无效离去＝阎尔梅劝朱由崧不成；贾兰逐鹿＝瞿式耜先后逐朱由崧、朱由榔二&quot;鹿&quot;；莺儿拿走红玉的笔＝范文程在满人奔袭北京之役中立功；&quot;詹光、单聘仁、程日兴、胡斯来&quot;＝沾光、擅骗人、成日兴、胡来，影射结交满人的奸商。</li></ol></li><li><strong>编者注（学界对照）</strong>：红学两大传统——蔡元培《石头记索隐》（1917）一系的索隐派主张&quot;吊明之亡，揭清之失&quot;的政治影射说；胡适《红楼梦考证》（1921）开创的考证派以曹雪芹家史自传说成为百年主流。190 帖属索隐派在民间的现代支流，傅山说未获学界采纳。其结构性弱点：影射体系不可证伪，谐音与&quot;深意&quot;自由度过大（如&quot;秃头和尚/癞头和尚&quot;之辨可正可反）；其强项恰是 C1 的时间线工作——那是硬碰硬的文本证据，与影射是否成立无关。民间考据的典型形态：<strong>硬证据与大胆假设绑在同一辆车上一并出售，读者须学会拆车。</strong></li></ul><h3 id="c3-最终结局-系列-史论八卦的方法-154" tabindex="-1">C3 &quot;最终结局&quot;系列：史论八卦的方法（154） <a class="header-anchor" href="#c3-最终结局-系列-史论八卦的方法-154" aria-label="Permalink to &quot;C3 &quot;最终结局&quot;系列：史论八卦的方法（154）&quot;">​</a></h3><ul><li><strong>选题法</strong>：专选&quot;有始有终&quot;的群体样本——末代督抚、民国开国都督、清十三王、北洋二十四上将、伪军十大将领、国军抗战八大新军将领——以&quot;收场&quot;为切片看大变局；每人小传三五行，末尾一句毒评定调（&quot;山西阎王果然名不虚传&quot;&quot;尚飨。活活!!!&quot;）。大人物的收场方式，本身就是制度与人性的测量仪。</li><li><strong>文体法</strong>：①用当代口语与赌局黑话（盘口、下注、变现）消解史论门槛；②文言戏仿——写华盛顿竟用《史记》列传笔法（&quot;公幼时曾不慎误伐一樱桃树，太公悉此事，以话试之，公以诚作答，乡人传为美谈&quot;），考据梗与文体游戏合一；③数据化对比——&quot;乱谈汉与罗马&quot;把汉卒与罗马兵的入伍年龄身高（23 岁/约 1 米 7 对 20 岁/约 1 米 77）、戍地（居延对不列颠）、装备清单（袍、袭、绔、枲履、六石具弩对靴、皮带、一剑一矛一盾）、月粮俸禄（日食五至六升、燧长月俸六百钱对月俸 65 第那尔）、随军家属供养制、烽火品约、战功赏格（&quot;斩捕虏首二级拜爵一次……尸身抢回置小棺材运回原籍礼葬&quot;）逐项列表——用居延汉简式的材料打&quot;八卦级&quot;的比武。</li><li><strong>盘口论</strong>：把政治转型当赌局分析——盘口开在何处（人事盘、经济盘、内鬼盘）、各方能力对比、运气三要素；并给出参照系（伊朗 79 年、罗马尼亚、波兰、台北），&quot;相同的盘口，不一定出相同的结果&quot;。名句：&quot;极权如同练邪门武功，因为邪所以命门一定有，这克服不了。可因为武功高，所以可以技术性解决老问题，可以移行换位，命门可以转到别处。&quot;</li><li><strong>成色评价</strong>：单篇细节难复核、立场先行，不能当史料直接引用；但&quot;结局视角＋数据表格＋参照系&quot;三件套，是可以借用的史论工具。</li></ul><h3 id="c4-去神话讲史法-111" tabindex="-1">C4 去神话讲史法（111） <a class="header-anchor" href="#c4-去神话讲史法-111" aria-label="Permalink to &quot;C4 去神话讲史法（111）&quot;">​</a></h3><ul><li><strong>异象还原</strong>：刘邦出生&quot;蛟龙附身&quot;的官方神话被还原为战国楚地开放民风下的一次偷情野合——旁证是秦始皇巡游楚地所立&quot;防隔内外，禁止淫佚&quot;的刻石；推理句：&quot;如果当时刘太公看到的不是一条蛟龙，而是隔壁村的王二麻子，那事情可能就更接近于真实。&quot;神话被解释为&quot;某人获得巨大成功之后，后来的崇拜者将之神化的结果&quot;。</li><li><strong>制度与经济打底</strong>：&quot;对于一个平民百姓而言，普天之下只有纳税和死亡是永恒不变的话题&quot;——用赋税、军功爵赏格、亭长职权这类制度细节把编年史还原为可感人事；刘邦的游侠习性、吕公嫁女的相面决策，都放在具体利益结构里讲。</li><li><strong>动机利益化</strong>：周亚夫平七国之乱&quot;把梁国抛出去消耗叛军、断其粮道&quot;的决策，从军事账与君臣猜忌两端解释；汉宣帝对霍光&quot;超规格办丧事&quot;的隐忍，从权力清算的时间差解释——忠奸叙事还原为利益与形势。</li><li><strong>成色评价</strong>：以《史记》《汉书》为底本的通俗化，推测处作者自认&quot;没有什么直接的证据&quot;；三帖中最稳的祛魅史学示范。</li></ul><h3 id="c5-民间考据通则-编者总结" tabindex="-1">C5 民间考据通则（编者总结） <a class="header-anchor" href="#c5-民间考据通则-编者总结" aria-label="Permalink to &quot;C5 民间考据通则（编者总结）&quot;">​</a></h3><p>四帖合观，民间考据的共性方法：①<strong>回到原文</strong>——190 逐词一致、154 用居延简牍数据、111 回到《史记》原文；②<strong>把矛盾当线索</strong>而非噪音（年龄错误、神话、反常数据皆如此）；③<strong>结论敢下但标注证据等级</strong>（&quot;没有什么直接的证据&quot;式的自白值得学习）；④<strong>用大众文体传播</strong>（打油诗、八卦、职场剧），代价是吸粉与失真的伴生。与学院方法相比，民间考据输在同行评审与版本控制，赢在问题意识与叙事活力——读它们要学的是方法，不是结论。</p>',35)])])}const c=o(i,[["render",r]]);export{d as __pageData,c as default};
